  "update.afterBackupOrphans":
    "Docker تصویری را که کانتینر پیش‌تر روی آن اجرا می‌شد، حالا بدون برچسب نگه می‌دارد و Unraid آن را به‌عنوان تصویر یتیم فهرست می‌کند. این باقی‌ماندهٔ طبیعی یک به‌روزرسانی موفق است، نه نشانهٔ شکست، و درست همان چیزی است که بازگشت سریع به تصویر پیشین لازم دارد. اگر نمی‌خواهید نگه‌داشته شود، در تنظیمات، کانتینرها، پاک‌سازی ایمیج و وضعیت به‌روزرسانی کلیدی هست که تصویر جایگزین‌شده را بلافاصله پس از به‌روزرسانی پاک می‌کند.",
