  "offsite.prune.title": "۵ · پاک‌سازی خارج از محل",
  "offsite.prune.info": "این گام فقط گزارش می‌دهد چه اتفاقی می‌افتد و چیزی را تنظیم نمی‌کند. اینکه این نسخه پاک‌سازی شود یا نه، با فقط-افزودنی در گام ۴ و مقادیر نگه‌داری در تنظیمات، نگه‌داری تعیین می‌شود. اگر باز هم می‌خواهی نسخه فقط-افزودنی را پاک‌سازی کنی، دستور restic forget --prune را در سمت فضای ذخیره‌سازی اجرا کن، یا با زمان‌بندی جداگانه خودش یا با بالا آوردن کوتاه‌مدت یک سرور REST دوم بدون فقط-افزودنی، پاک‌سازی از طریق آن و سپس خاموش کردن دوباره‌اش.",
  "offsite.prune.stateFarSide": "از اینجا هیچ چیز این نسخه را پاک‌سازی نمی‌کند. فقط-افزودنی روشن است، پس BombVault تنها به آن می‌افزاید و پاک‌سازی کار سمت فضای ذخیره‌سازی است.",
  "offsite.prune.statePolicy": "BombVault این نسخه را پس از هر تکثیر، بر پایه سیاست نگه‌داری خارج از محل پاک‌سازی می‌کند.",
  "offsite.prune.stateNone": "هیچ چیز این نسخه را پاک‌سازی نمی‌کند. فقط-افزودنی خاموش است و همه مقادیر نگه‌داری خارج از محل ۰ هستند، پس تا جایی که دیسک جا دارد رشد می‌کند.",
  "offsite.prune.effective": "نگه‌داری {last} تازه‌ترین، {daily} روزانه، {weekly} هفتگی، {monthly} ماهانه، {yearly} سالانه.",
  "offsite.prune.editedElsewhere": "در تنظیمات، نگه‌داری تعیین می‌شود. همه منابع این مقادیر را مشترک دارند، مگر منبعی که قواعد خودش را دارد.",
  "offsite.prune.budgetInfo": "به‌محض اینکه مخزن خارج از محل از این تعداد گیگابایت بیشتر شود هشدار می‌دهد. هرگز چیزی را حذف نمی‌کند، پس تور ایمنی نسخه‌ای است که هیچ چیز پاک‌سازی‌اش نمی‌کند.",
  "settings.retentionImmutableNotPruned": "مقصد خارج از محلی که فقط-افزودنی است هرگز از اینجا پاک‌سازی نمی‌شود، هر چه این مقادیر بگویند. گام مربوط به آن در دستیار خارج از محل توضیح می‌دهد چطور آن را از سمت فضای ذخیره‌سازی پاک‌سازی کنی.",

