  "hooks.hint": "دستورها با sh -c داخل کانتینر اجرا می‌شوند. دستور پیش‌اجرا قبل از پشتیبان‌گیری اجرا می‌شود؛ از آن برای آماده‌سازی داده‌ای که باید پشتیبان‌گیری شود استفاده کنید، مثلاً نوشتن یک حافظه نهان روی دیسک. از پایگاه‌های داده شناخته‌شده به‌طور خودکار دامپ گرفته می‌شود و هوک لازم ندارند. اگر دستور پیش‌اجرا شکست بخورد، پشتیبان‌گیری لغو می‌شود. دستور پس‌اجرا پس از اجرای دوباره کانتینر اجرا می‌شود و شکست آن فقط ثبت می‌شود. هوک‌ها فقط دستور اجرا می‌کنند، پوشه‌ای به پشتیبان‌گیری اضافه نمی‌کنند.",
