  "dbdump.toggle": "تخلیهٔ پایگاه داده پیش از هر پشتیبان‌گیری",
  "dbdump.toggleHint": "BombVault این کانتینر را به عنوان پایگاه دادهٔ {engine} شناخت. پیش از هر پشتیبان‌گیری از سرور در حال اجرا یک تخلیهٔ کامل SQL می‌خواهد و آن را به عنوان نقطهٔ بازیابی مستقل، مستقیم در مخزن پشتیبان می‌گذارد، بدون نوشتن هیچ فایلی روی دیسک‌های شما. بازیابی از پشتیبان فایل‌ها استفاده می‌کند که پس از توقف کانتینر گرفته می‌شود؛ تخلیه نسخهٔ دومی است که می‌توانید دانلود یا وارد کنید. تخلیهٔ ناموفق هرگز پشتیبان‌گیری را ناموفق نمی‌کند، بلکه به صورت اجرای ناموفق مستقل دیده می‌شود.",
  "dbdump.toggleHintLabel": "برچسب کانتینر bombvault.dbdump تخلیه را برای این پایگاه دادهٔ {engine} روشن می‌کند. پیش از هر پشتیبان‌گیری BombVault از سرور در حال اجرا یک تخلیهٔ کامل SQL می‌خواهد و آن را به عنوان نقطهٔ بازیابی مستقل نگه می‌دارد. تخلیهٔ ناموفق هرگز پشتیبان‌گیری را ناموفق نمی‌کند، بلکه به صورت اجرای ناموفق مستقل دیده می‌شود.",
  "dbdump.toggleHintOnlyCopy": "پیش از هر پشتیبان‌گیری BombVault از این سرور {engine} در حال اجرا یک تخلیهٔ کامل SQL می‌خواهد و آن را به عنوان نقطهٔ بازیابی مستقل نگه می‌دارد. در این کانتینر، تخلیه تنها نسخهٔ یکدست پایگاه داده است: پوشهٔ دادهٔ آن یا در حین اجرای سرور کپی می‌شود یا در هیچ پشتیبانی نیست. تخلیه را روشن بگذارید. تخلیهٔ ناموفق هرگز پشتیبان‌گیری را ناموفق نمی‌کند، بلکه به صورت اجرای ناموفق مستقل دیده می‌شود.",
  "dbdump.toggleHintUnknown": "پیش از هر پشتیبان‌گیری BombVault از این سرور {engine} در حال اجرا یک تخلیهٔ کامل SQL می‌خواهد و آن را به عنوان نقطهٔ بازیابی مستقل نگه می‌دارد. مشخص نشد این کانتینر پوشهٔ دادهٔ خود را کجا نگه می‌دارد، پس معلوم نیست پشتیبان فایل‌ها نسخهٔ قابل استفاده‌ای دارد یا نه. تخلیه همان نسخه‌ای است که می‌توانید روی آن حساب کنید. آن را روشن بگذارید. تخلیهٔ ناموفق هرگز پشتیبان‌گیری را ناموفق نمی‌کند، بلکه به صورت اجرای ناموفق مستقل دیده می‌شود.",
  "dbdump.lookalikeHint": "این کانتینر شبیه پایگاه دادهٔ {engine} است، اما BombVault ایمیج آن را با اطمینان نمی‌شناسد. اگر واقعاً چنین است تخلیه را روشن کنید؛ اگر بعد از آن ناموفق شد، یعنی ایمیج از تنظیمات معمول پیروی نمی‌کند و می‌توانید دوباره خاموشش کنید.",
  "dbdump.engineLabel": "نوع پایگاه داده",
  "dbdump.labelOff": "با برچسب کانتینر bombvault.dbdump=false خاموش شده است.",
