  "dbdump.offConfirmLive": "تخلیهٔ این پایگاه داده خاموش شود؟ پوشهٔ دادهٔ آن در حین اجرای سرور کپی می‌شود، پس بدون تخلیه هیچ نسخهٔ یکدستی وجود ندارد.",
