  "dbdump.busyImporting": "در حال وارد کردن تخلیهٔ پایگاه داده...",
  "dbdump.updateWarn": "این یک پایگاه داده است. به‌روزرسانی ایمیج می‌تواند آن را به نسخهٔ اصلی تازه‌ای ببرد که پوشهٔ دادهٔ قدیمی را نمی‌پذیرد. آنگاه تخلیه‌ای که درست پیش از به‌روزرسانی گرفته شده از پنل پشتیبان‌ها به نسخهٔ جدید وارد می‌شود.",
  "dbdump.updateWarnSameMajor": "این یک پایگاه داده است. به‌روزرسانی ایمیج می‌تواند آن را به نسخهٔ اصلی تازه‌ای ببرد. MySQL و MariaDB تخلیه را فقط در همان نسخهٔ اصلی که از آن آمده وارد می‌کنند، پس اگر نسخهٔ جدید پوشهٔ دادهٔ قدیمی را نپذیرفت، ایمیج را به نسخهٔ قبلی برگردانید و تخلیه‌ای را که درست پیش از به‌روزرسانی گرفته شده همان‌جا وارد کنید.",
  "dbdump.stackRestoreWarn": "one=دادهٔ {names} در حین اجرای استک کپی می‌شود. پس از بازیابی، پیش از استفاده از برنامه تازه‌ترین تخلیهٔ پایگاه دادهٔ آن را وارد کنید.|other=دادهٔ {names} در حین اجرای استک کپی می‌شود. پس از بازیابی، پیش از استفاده از برنامه‌ها تازه‌ترین تخلیهٔ پایگاه دادهٔ آن‌ها را وارد کنید.",
  "dbdump.introNotice": "one=BombVault پیش از هر پشتیبان‌گیری از پایگاه‌های داده‌ای که می‌شناسد تخلیه می‌گیرد، به عنوان نقاط بازیابی مستقل. شناخته‌شده در اینجا: {n} پایگاه داده، {name}. می‌توانید این را برای هر کانتینر روی کارت آن یا برای همهٔ کانتینرها در تنظیمات خاموش کنید.|other=BombVault پیش از هر پشتیبان‌گیری از پایگاه‌های داده‌ای که می‌شناسد تخلیه می‌گیرد، به عنوان نقاط بازیابی مستقل. شناخته‌شده در اینجا: {n} پایگاه داده، نخستین آن‌ها {name}. می‌توانید این را برای هر کانتینر روی کارت آن یا برای همهٔ کانتینرها در تنظیمات خاموش کنید.",
  "dbdump.introDismiss": "متوجه شدم",
  "dbdump.fixAuth": "متغیرهای گذرواژه را روی خود کانتینر پایگاه داده بررسی کنید (مثلاً POSTGRES_PASSWORD، MARIADB_ROOT_PASSWORD یا MYSQL_ROOT_PASSWORD، یا نسخه‌های _FILE آن‌ها). تخلیه دقیقاً از همان‌ها استفاده می‌کند.",
  "dbdump.fixPrivileges": "تخلیه فقط توانست با کاربر برنامه وارد شود که یکی از دسترسی‌های لازم را ندارد. به کانتینر یک گذرواژهٔ root واقعی بدهید نه گذرواژه‌ای تصادفی.",
  "dbdump.fixUnreachable": "سرور پایگاه داده روی سوکت محلی خود پاسخ نداد. لاگ کانتینر را ببینید، شاید هنوز در حال بالا آمدن باشد یا از کار افتاده باشد.",
  "dbdump.fixNotRunning": "هنگام اجرای پشتیبان‌گیری، کانتینر متوقف موقت یا در حال راه‌اندازی دوباره بود. اگر مدام راه‌اندازی می‌شود لاگ آن را ببینید.",
  "dbdump.fixNoClient": "ایمیج ابزار تخلیه ندارد. از ایمیج رسمی استفاده کنید یا تخلیه را برای این کانتینر خاموش کنید.",
  "dbdump.fixSecret": "کاربر کانتینر نتوانست فایل گذرواژهٔ نام‌برده در متغیر _FILE را بخواند. مسیر و دسترسی‌های آن را بررسی کنید.",
  "dbdump.fixNoCredentials": "تنظیمات کانتینر نه گذرواژهٔ root دارد و نه کاربری با پایگاه داده. MARIADB_ROOT_PASSWORD (یا MYSQL_ROOT_PASSWORD) را تنظیم کنید، یا یک کاربر و یک پایگاه داده.",
  "dbdump.fixNeedsUpgrade": "جدول‌های سیستمی پایگاه داده از نسخه‌ای قدیمی‌تر هستند. متغیر MARIADB_AUTO_UPGRADE را با مقدار 1 به کانتینر بیفزایید و آن را دوباره راه‌اندازی کنید، یا یک بار mariadb-upgrade را داخل کانتینر اجرا کنید.",
  "dbdump.fixTimeout": "تخلیه به محدودیت زمانی خود رسید. برای پایگاه دادهٔ بسیار بزرگ، متغیر DB_DUMP_MAX_HOURS را به کانتینر BombVault بیفزایید (Unraid: کانتینر را ویرایش کنید، Add another Path, Port, Variable)، مثلاً 12.",
  "dbdump.fixBackupCap": "کل پشتیبان‌گیری در حالی که تخلیه هنوز اجرا می‌شد به BACKUP_MAX_HOURS رسید. مقدار BACKUP_MAX_HOURS را روی کانتینر BombVault بالا ببرید.",
  "dbdump.fixStalled": "تخلیه از پیشروی بازماند، معمولاً چون برنامه قفلی را نگه داشته بود. با پشتیبان‌گیری بعدی دوباره تلاش می‌شود.",
  "dbdump.fixDumpData": "ابزار تخلیه با پیام نشان‌داده‌شده متوقف شد. با پشتیبان‌گیری بعدی دوباره تلاش می‌شود؛ اگر باز هم ناموفق بود، آن پیام علت را می‌گوید.",
  "dbdump.fixDocker": "Docker فرمان تخلیه را اجرا نکرد. معمولاً کانتینر هنگام شروع پشتیبان‌گیری متوقف، معلق یا دوباره ساخته شده است. با پشتیبان‌گیری بعدی دوباره تلاش می‌شود؛ اگر ادامه یافت سرویس Docker و دسترسی BombVault به آن را بررسی کنید.",
  "dbdump.fixRepository": "مخزن پشتیبان تخلیه را نپذیرفت، یا بایت کمتری از آنچه تخلیه شد ذخیره کرد. مخزن را در تنظیمات، فضای ذخیره‌سازی بررسی کنید؛ تخلیه با پشتیبان‌گیری بعدی دوباره تلاش می‌شود.",
  "dbdump.fixLeftover": "تخلیهٔ آسیب‌دیده از مخزن پاک نشد. آن را از فهرست تخلیه‌ها در پنل پشتیبان‌ها حذف کنید.",
  "dbdump.fixHelper": "دستیار تخلیهٔ BombVault بدون نتیجه به پایان رسید. اگر تکرار شد، گزارشی باز کنید و بستهٔ تشخیصی را پیوست کنید.",
  "dbdump.listTitle": "برون‌ریزهای پایگاه داده",
  "dbdump.listHint": "هر برون‌ریز یک خروجی کامل SQL است که درست پیش از پشتیبان‌گیری از پایگاه دادهٔ در حال اجرا گرفته می‌شود. BombVault هرگز خودش برون‌ریز را بازنمی‌گرداند: بازگردانی کانتینر فایل‌هایش را برمی‌گرداند و اگر آن فایل‌ها هنگام توقف کانتینر ذخیره شده باشند، نسخهٔ تازه‌ترند. وقتی آن فایل‌ها به کار نمی‌آیند از برون‌ریز استفاده کن: وقتی در حال اجرای سرور کپی شده‌اند یا اصلاً کپی نشده‌اند، وقتی پایگاه داده به نسخهٔ اصلی تازه‌ای رفته یا پوشهٔ داده آسیب دیده است. درون‌ریزی برون‌ریز را در یک پایگاه دادهٔ خالی تازه‌راه‌افتاده می‌گذارد و پوشهٔ دادهٔ قدیمی را کنار آن نگه می‌دارد. یک فایل کامل .sql با خط توضیح \"complete\" پایان می‌یابد.",
