  // Restore from another BombVault repo
  "recovery.foreignTitle": "بازیابی از یک مخزن BombVault دیگر",
  "recovery.abTitle": "وارد کردن از افزونهٔ Appdata.Backup",
  "recovery.abIntro": "بایگانی‌هایی را که افزونهٔ Appdata.Backup نوشته است به نقطه‌های بازیابی کانتینرهای متناظر تبدیل می‌کند، هر کدام با تاریخی که افزونه آن را ساخته است. بایگانی‌ها فقط خوانده می‌شوند و هرگز تغییر نمی‌کنند یا پاک نمی‌شوند. هر بایگانی کنار مخزن باز می‌شود، پشتیبان‌گیری می‌شود و نسخهٔ بازشده دوباره پاک می‌شود، پس آنجا باید برای بزرگ‌ترین بایگانی جا باشد.",
