  "mcp.title": "سرور MCP",
  "mcp.hint": "به دستیارهای هوش مصنوعی مانند Claude اجازه می‌دهد وضعیت پشتیبان‌گیری این سرور را بخوانند، پشتیبان‌گیری را آغاز کنند و آنچه را خودشان آغاز کرده‌اند لغو کنند، از طریق Model Context Protocol. بازگردانی، حذف و تنظیمات در همین رابط وب می‌مانند.",
