  "mcp.statusNoneWorks": "خاموش: هیچ کلیدی کار نمی‌کند",
  "mcp.noPasswordWarning": "رمز ورودی تنظیم نشده است، بنابراین این رابط وب برای همه در شبکه‌ات باز است و هر کس بتواند آن را باز کند می‌تواند کلید هم بسازد.",
  "mcp.setPassword": "یک رمز ورود تعیین کن",
  "mcp.needsPasswordForHost": "این صفحه با نام {host} باز شده است. بدون رمز ورود، کلیدها فقط از یک نشانی IP یا نامی محلی مانند tower یا tower.local ساخته و جایگزین می‌شوند تا هیچ صفحه‌ای در اینترنت نتواند کلیدی بسازد. تعیین رمز ورود این محدودیت را برای این نشانی برمی‌دارد. می‌توانی BombVault را از نشانی محلی‌اش هم باز کنی.",
  "mcp.restoreRevokedNotice": "بازگردانی پیکربندی همهٔ کلیدهای MCP را باطل کرد. برای دستیارهایت کلیدهای تازه بساز.",
  "mcp.appKeyChanged": "APP_KEY از زمان ساخت این کلیدها تغییر کرده است، پس دیگر کار نمی‌کنند. هر کلید را جایگزین کن و دستیارهایت را به‌روز کن.",
  "mcp.keyUnusable": "پس از تغییر APP_KEY دیگر معتبر نیست",
