  "mcp.endpointLabel": "نقطهٔ اتصال",
  "mcp.endpointHint": "نشانی‌ای که دستیارت به آن وصل می‌شود. با Streamable HTTP کار می‌کند و کلیدی در سرآیند Authorization یا X-API-Key انتظار دارد، یا توکن دسترسی پس از آنکه دستیار با OAuth وارد شد.",
  "mcp.newKey": "کلید تازه",
  "mcp.labelLabel": "نام کلید",
  "mcp.labelPlaceholder": "Claude Code روی لپ‌تاپ",
  "mcp.allowStart": "اجازهٔ آغاز پشتیبان‌گیری",
  "mcp.allowStartHint": "با روشن بودن این گزینه، دستیار می‌تواند از یک مورد، یک دامنهٔ کامل یا Backup Everything پشتیبان بگیرد و پشتیبان‌هایی را که خودش آغاز کرده لغو کند: حداکثر {n} در ساعت، با فاصلهٔ {minutes} دقیقه برای همان مورد و {perDay} برای هر مورد در روز. پشتیبان‌گیری کانتینرهای در حال اجرا را تا پایان کار متوقف می‌کند. بدون آن، کلید فقط می‌تواند بخواند.",
