  "mcp.newKeyTitle": "کلید تازهٔ تو",
  "mcp.showOnce": "همین حالا رونوشت بگیر. BombVault فقط اثر انگشتی از آن نگه می‌دارد و نمی‌تواند دوباره نشانش دهد.",
  "mcp.copyKey": "رونوشت کلید",
  "mcp.dismissKey": "رونوشت گرفتم",
  "mcp.snippetsLabel": "اتصال یک کلاینت",
  "mcp.connectHint": "کلاینتت را انتخاب کن تا راه‌اندازی مخصوص خودش را بگیری: کلیدی با نام آن، پیکربندی برای رونوشت و مرحلهٔ گواهی‌ای که لازم دارد. هر کلاینت دیگری از راه کلاینت دیگر وصل می‌شود. آنچه دستیار می‌خواند، مانند نام موردها، تاریخچه و پیام‌های خطا، به ارائه‌دهندهٔ هوش مصنوعی پشت آن می‌رسد، پس از آنکه BombVault مسیرهای میزبان، مکان مخزن‌ها و اطلاعات ورود را حذف کرد.",
  "mcp.groupLocal": "روی این رایانه",
  "mcp.groupCloud": "در ابر",
  "mcp.cloudWarningTitle": "BombVault باید از اینترنت در دسترس باشد",
  "mcp.cloudWarning": "این سرویس‌ها BombVault را از سرورهای ارائه‌دهندهٔ خود صدا می‌زنند، نه از رایانهٔ تو. پس BombVault باید با گواهی‌ای که به‌طور عمومی معتبر است از اینترنت در دسترس باشد، مثلاً پشت یک پراکسی معکوس. ورود روی آن پراکسی می‌تواند از رابط وب محافظت کند، اما ‎/mcp باید تا BombVault عبور کند که خودش کلید را بررسی می‌کند؛ این سرویس‌ها نمی‌توانند در پراکسی وارد شوند. Le Chat گواهی‌های خودامضا را رد می‌کند.",
