  "oauth.unnamedClient": "یک کلاینت بی‌نام",
  "oauth.errorOff": "ورود با OAuth در این BombVault روشن نیست. در تنظیمات، یکپارچه‌سازی‌ها، سرور MCP روشن می‌شود.",
  "oauth.errorUnknownClient": "این کلاینت اینجا ثبت نشده یا ثبتش منقضی شده است. BombVault را از کلاینت حذف کن و دوباره اضافه‌اش کن.",
  "oauth.errorBadRedirect": "این درخواست نشانی بازگشتی را نام می‌برد که کلاینت هرگز ثبت نکرده است، پس BombVault تو را آنجا نمی‌فرستد.",
  "oauth.errorInvalid": "کلاینت چیزی خواست که BombVault پشتیبانی نمی‌کند، پس ورود همین‌جا متوقف می‌شود.",
